changeSet.sql:
CREATE TABLE orders_type_upgrade (
    id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
    orderid VARCHAR(50), qty DOUBLE DEFAULT 1.0, details VARCHAR(255),
    attributes VARCHAR(255), notes VARCHAR(255), ticketid VARCHAR(50),
    ordertime DATETIME NOT NULL, displayid VARCHAR(50) DEFAULT '1',
    auxiliary INT, completetime DATETIME
);
INSERT INTO orders_type_upgrade
    (id, orderid, qty, details, attributes, notes, ticketid, ordertime, displayid, auxiliary, completetime)
SELECT id, orderid, CAST(qty AS REAL), details, attributes, notes, ticketid,
       ordertime, CAST(displayid AS TEXT), auxiliary, completetime FROM orders;
UPDATE sqlite_sequence SET seq = MAX(seq, COALESCE(
    (SELECT seq FROM sqlite_sequence WHERE name = 'orders'), 0))
    WHERE name = 'orders_type_upgrade';
DROP TABLE orders;
ALTER TABLE orders_type_upgrade RENAME TO orders;
